insert into public.styles(id,data) values ('dz',$wd${"id": "dz", "name": "Dumbbell Zumba fitness", "h": 96, "blurb": "Zumba with light dumbbells: dance cardio plus strength and toning, set to music.", "curriculum": [{"level": "Foundation", "items": ["Basic Zumba steps: merengue, salsa, cumbia and reggaeton", "Holding and moving with 1–2 kg dumbbells safely", "Toning moves for arms, shoulders, back and core", "Squats and lunges to music for legs and glutes", "Pacing your breathing through a full hour of cardio"]}, {"level": "Progressive", "items": ["Faster combinations and longer cardio blocks", "Heavier dumbbells (2–3 kg) and more repetitions", "Interval routines for fat burn and stamina", "A monthly check of stamina, strength and flexibility"]}], "kit": {"name": "Not required", "fee": 0}}$wd$::jsonb) on conflict (id) do update set data=excluded.data, updated_at=now();
insert into public.styles(id,data) values ('zu',$wd${"id": "zu", "name": "Zumba fitness", "h": 322, "blurb": "Dance cardio to Latin and Indian beats. All fitness levels welcome.", "curriculum": [{"level": "All levels", "items": ["Core Zumba rhythms: merengue, salsa, cumbia and reggaeton", "Bollywood and Indian folk-beat routines", "Following the instructor’s cues and changing steps with the music", "Building stamina through high and low intensity songs", "Better coordination and balance"]}, {"level": "Progressive", "items": ["Longer, faster routines", "High-intensity interval songs", "A monthly stamina check"]}], "kit": {"name": "Not required", "fee": 0}}$wd$::jsonb) on conflict (id) do update set data=excluded.data, updated_at=now();
insert into public.styles(id,data) values ('wh',$wd${"id": "wh", "name": "Western / Hip hop (kids & teens)", "h": 200, "blurb": "Western and hip hop for kids and teens: grooves, choreography, musicality and stage confidence.", "curriculum": [{"level": "Beginner", "items": ["Bounce, rock and basic hip hop grooves", "Jazz and contemporary basics: posture, lines and spins", "Counting music in 8s and staying on the beat", "Isolations: head, chest, shoulders and hips", "Learning and remembering a full routine every month"]}, {"level": "Intermediate", "items": ["Popping and locking basics", "Turns, jumps, floor work and smooth transitions", "Freestyle confidence and dance battles", "Group formations and a showcase performance"]}], "kit": {"name": "Not required", "fee": 0}}$wd$::jsonb) on conflict (id) do update set data=excluded.data, updated_at=now();
insert into public.styles(id,data) values ('bn',$wd${"id": "bn", "name": "Bharatanatyam", "h": 352, "request": true, "blurb": "Classical dance of Tamil Nadu: rhythm, geometry and storytelling through abhinaya.", "curriculum": [{"level": "Foundation", "items": ["Namaskaram (salutation) and araimandi (half-sitting posture)", "Adavus: Tatta, Natta, Visharu and Kuditta mettu", "Asamyuta hastas (single-hand mudras) and their meanings", "Keeping talam: counting Adi talam in three speeds", "Eye, neck and head movements"]}, {"level": "Intermediate", "items": ["Samyuta hastas (double-hand mudras)", "Navarasa: the nine expressions", "Alarippu and Jathiswaram", "Shabdam: storytelling through abhinaya"]}, {"level": "Advanced", "items": ["Varnam: the main piece combining nritta and abhinaya", "Padam, Keertanam and Thillana", "Stage presence and costume", "Arangetram (debut performance) preparation"]}], "kit": {"name": "Not required", "fee": 0}}$wd$::jsonb) on conflict (id) do update set data=excluded.data, updated_at=now();
insert into public.styles(id,data) values ('yo',$wd${"id": "yo", "name": "Yoga", "h": 160, "request": true, "blurb": "Asanas, breathing and flexibility for all ages. Batches and timings arranged on request.", "curriculum": [{"level": "All levels", "items": ["Sun salutations (Surya Namaskar)", "Standing, seated and balancing asanas", "Pranayama: breathing for calm and energy", "Flexibility, posture and back care", "Relaxation and a short guided meditation"]}], "kit": {"name": "Not required", "fee": 0}}$wd$::jsonb) on conflict (id) do update set data=excluded.data, updated_at=now();
insert into public.styles(id,data) values ('fu',$wd${"id": "fu", "name": "Fusion", "h": 275, "request": true, "blurb": "Indian classical vocabulary blended with contemporary and western movement.", "curriculum": [{"level": "Beginner", "items": ["Classical basics: posture, mudras and footwork", "Contemporary basics: flow, floor work and release", "Blending Indian rhythm with western music", "Expressions and storytelling"]}, {"level": "Intermediate", "items": ["Creating short pieces of your own", "Partner and group choreography", "A showcase piece for events"]}], "kit": {"name": "Not required", "fee": 0}}$wd$::jsonb) on conflict (id) do update set data=excluded.data, updated_at=now();
insert into public.styles(id,data) values ('wd',$wd${"id": "wd", "name": "Wedding choreography", "h": 44, "request": true, "blurb": "Sangeet and reception performances for couples, families and friends.", "curriculum": [{"level": "What’s included", "items": ["Choosing songs and editing a custom mix", "Couple dance with easy, elegant steps made for you", "Family and friends group numbers", "Entry and exit sequences for the sangeet", "Full rehearsal and a final run-through before the event"]}], "kit": {"name": "Not required", "fee": 0}}$wd$::jsonb) on conflict (id) do update set data=excluded.data, updated_at=now();
insert into public.styles(id,data) values ('sc',$wd${"id": "sc", "name": "Semi-classical", "h": 14, "request": true, "blurb": "Classical technique set to film and devotional songs. Graceful, expressive, stage-ready.", "curriculum": [{"level": "Beginner", "items": ["Basic mudras and footwork from classical dance", "Bhava: facial expressions and emotion", "A complete routine on a film or devotional song"]}, {"level": "Intermediate", "items": ["Graceful classical movement on film songs", "Group formations for the stage", "A full stage performance piece"]}], "kit": {"name": "Not required", "fee": 0}}$wd$::jsonb) on conflict (id) do update set data=excluded.data, updated_at=now();
insert into public.styles(id,data) values ('pc',$wd${"id": "pc", "name": "Customised personal classes", "h": 260, "request": true, "blurb": "One-to-one or small-group sessions in any style, at a time and place that suits you.", "curriculum": [{"level": "Made for you", "items": ["Any style: classical, Bollywood, western, Zumba or yoga", "Your goal: fitness, a performance, a wedding or a new skill", "Flexible days and timings", "Classes at your home or community hall", "One-to-one attention with a plan made for you", "A progress review every month"]}], "kit": {"name": "Not required", "fee": 0}}$wd$::jsonb) on conflict (id) do update set data=excluded.data, updated_at=now();
