insert into public.settings(id,data) values ('main',$wd${"studio": "WiniD Hub", "tagline": "Where moments become art · Chennai", "welcome": "Dance and fitness classes right inside your apartment community. Sign in to see your classes, attendance and fees.", "bank": {"payee": "MANASWINI", "acct": "270801507749", "ifsc": "ICIC0002708", "bank": "ICICI Bank", "branch": "Siruseri, OMR, Chennai 600130", "upi": ""}, "regFee": 500, "dueDay": 5, "lateFee": 100, "siblingDiscount": 10, "communityNote": "Classes in apartment communities need at least 8 sign-ups to start a batch.", "wa": {"number": "9940462190", "sender": "Manaswini", "role": "Founder", "optIn": true, "enquiry": "Namaste {name}! This is {sender}, founder of {studio}. Thank you for your enquiry about {style}{timing}.\n\nI would love to help you choose the right batch and answer any questions. You can reply here or call me on {number}.\n\n{studio} · Where moments become art", "welcome": "Namaste {name}! Welcome to {studio}. I am {sender}, the founder.\n\nYour profile is ready, so you can now choose a class timing and join from our website. If you need help picking a style or batch, just reply to this message or call me on {number}.\n\n{studio} · Where moments become art", "request": "Namaste {name}! This is {sender} from {studio}. We have received your request to join {style}{timing}.\n\nAmount to pay when you join: {amount}. You can pay from the Fees page on our website, by Google Pay or any UPI app to {upi}. I will confirm your seat shortly.\n\n{studio} · Where moments become art", "overdue": "Namaste {name}, this is {sender} from {studio}. Your fee of {amount} for {items}{due}.\n\nPlease pay today by Google Pay or any UPI app to {upi}, or at the front desk, so your classes continue without a break. Please ignore this if you have already paid. Thank you!", "cancel": "Namaste {name}, this is {sender} from {studio}. Your {style} class on {date} is cancelled ({reason}). {makeup}\n\nSorry for the inconvenience. Reply here if you have any questions.", "makeup": "Namaste {name}, this is {sender} from {studio}. Your make-up class for the cancelled {style} class on {date} is on {mdate}, {mtime} at {mplace}. See you there!\n\n{studio} · Where moments become art", "birthday": "Happy birthday, {name}! Wishing you a wonderful year full of music, movement and joy. Everyone at {studio} is cheering for you today.\n\nWith love,\n{sender}, {studio}", "festival": "Happy {festival}, {name}! Wishing you and your family a joyful and peaceful celebration.\n\nWith warm wishes,\n{sender} and the {studio} family", "resume": "Namaste {name}, this is {sender} from {studio}. We have missed you in {style} class{timing}! We would love to see you back this week. If you need a different timing or any help, just reply here or call me on {number}.\n\n{studio} · Where moments become art", "reminder": "Namaste {name}, this is {sender} from {studio}. A gentle reminder that {amount} is due for {items}{due}.\n\nYou can pay by Google Pay or any UPI app to {upi}, or at the front desk. Please ignore this if you have already paid. Thank you!"}}$wd$::jsonb) on conflict (id) do update set data=excluded.data, updated_at=now();
insert into public.admin_state(id,data) values ('main','{}'::jsonb) on conflict (id) do nothing;
